INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('efe2d280-f37a-5563-8e05-7edc1487c6d3', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'igcse', NULL, NULL, 36, 36, 'A 0.50 kg ball on a 0.80 m string moves in a horizontal circle on a frictionless table. It completes 3.0 revolutions in 2.0 s. Calculate the tension in the string.', 'diagram:circ-ch-ball-table', 2, 'numeric'::answer_type, '35.53', 'N', NULL, false, 'Period: T = 2.0 s ÷ 3.0 rev = 0.667 s. (a) Speed: v = 2πr/T = 2π × 0.80 ÷ 0.667 = 7.54 m/s. (b) The tension is the only horizontal force, so it provides the centripetal force: T = mv²/r = 0.50 × 7.54² ÷ 0.80 = 35.5 N. Check: ω = 2π × 1.5 = 9.42 rad/s and mω²r gives the same.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('a52b8276-7d1a-5ceb-89c3-324e2481f17c', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 46, 46, 'A 0.50 kg ball on a 0.80 m string moves in a horizontal circle on a frictionless table. It completes 3.0 revolutions in 2.0 s. Calculate the tension in the string.', 'diagram:circ-ch-ball-table', 2, 'numeric'::answer_type, '35.53', 'N', NULL, false, 'Period: T = 2.0 s ÷ 3.0 rev = 0.667 s. (a) Speed: v = 2πr/T = 2π × 0.80 ÷ 0.667 = 7.54 m/s. (b) The tension is the only horizontal force, so it provides the centripetal force: T = mv²/r = 0.50 × 7.54² ÷ 0.80 = 35.5 N. Check: ω = 2π × 1.5 = 9.42 rad/s and mω²r gives the same.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('fd00f3e6-966e-5367-85d3-946cab18c5d9', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'igcse', NULL, NULL, 37, 37, 'A 1200 kg car takes a flat circular bend of radius 50 m. On a dry road the tyres can provide a maximum friction force of 7200 N. On a wet road this maximum falls by 40%. Calculate the maximum safe speed on the wet road.', 'diagram:circ-ch-car-bend', 2, 'numeric'::answer_type, '13.42', 'm/s', 0.05, false, 'Friction provides the centripetal force, F = mv²/r, so v = √(Fr/m). (a) Dry: v = √(7200 × 50 ÷ 1200) = √300 = 17.3 m/s. (b) Wet: the friction is 0.60 × 7200 = 4320 N, so v = √(4320 × 50 ÷ 1200) = √180 = 13.4 m/s. The speed falls by a factor of √0.6 ≈ 0.77, not 0.6, because v ∝ √F.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('d8c38db0-41a8-52e7-8f0a-8fc093509fb6', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 47, 47, 'A 1200 kg car takes a flat circular bend of radius 50 m. On a dry road the tyres can provide a maximum friction force of 7200 N. On a wet road this maximum falls by 40%. Calculate the maximum safe speed on the wet road.', 'diagram:circ-ch-car-bend', 2, 'numeric'::answer_type, '13.42', 'm/s', 0.05, false, 'Friction provides the centripetal force, F = mv²/r, so v = √(Fr/m). (a) Dry: v = √(7200 × 50 ÷ 1200) = √300 = 17.3 m/s. (b) Wet: the friction is 0.60 × 7200 = 4320 N, so v = √(4320 × 50 ÷ 1200) = √180 = 13.4 m/s. The speed falls by a factor of √0.6 ≈ 0.77, not 0.6, because v ∝ √F.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('d2630028-976a-5096-9879-fb3ecec4b182', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'igcse', NULL, NULL, 38, 38, 'Two coins sit on a turntable rotating at 45 revolutions per minute. Coin A is 0.10 m from the centre and coin B is 0.20 m from the centre. Calculate the centripetal acceleration of coin B.', 'diagram:circ-ch-turntable', 2, 'numeric'::answer_type, '4.441', 'm/s²', NULL, false, 'Both coins turn together, so they share the same angular speed: ω = 45 × 2π ÷ 60 = 4.71 rad/s. (a) v = ωr, so v ∝ r and v_B/v_A = 0.20/0.10 = 2. (b) a = ω²r = 4.71² × 0.20 = 4.44 m/s².', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('bb7476c6-dfaa-5c8f-a391-864a6a67811d', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 48, 48, 'Two coins sit on a turntable rotating at 45 revolutions per minute. Coin A is 0.10 m from the centre and coin B is 0.20 m from the centre. Calculate the centripetal acceleration of coin B.', 'diagram:circ-ch-turntable', 2, 'numeric'::answer_type, '4.441', 'm/s²', NULL, false, 'Both coins turn together, so they share the same angular speed: ω = 45 × 2π ÷ 60 = 4.71 rad/s. (a) v = ωr, so v ∝ r and v_B/v_A = 0.20/0.10 = 2. (b) a = ω²r = 4.71² × 0.20 = 4.44 m/s².', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('7f230135-c5c8-5224-8fce-5074843ac903', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'igcse', NULL, NULL, 39, 39, 'A 0.50 kg ball is swung in a vertical circle of radius 1.2 m. Assume its speed is 6.0 m/s at both the top and the bottom. Calculate the tension in the string at the top of the circle. Take g = 9.8 N/kg.', 'diagram:circ-ch-vertical', 3, 'numeric'::answer_type, '10.1', 'N', NULL, false, 'The centripetal force needed is mv²/r = 0.50 × 36 ÷ 1.2 = 15.0 N, and the weight is mg = 0.50 × 9.8 = 4.90 N. (a) At the top the tension and the weight both point towards the centre: T + mg = 15.0, so T = 15.0 − 4.90 = 10.1 N. (b) At the bottom the tension points to the centre but the weight points away: T − mg = 15.0, so T = 19.9 N. (c) The string just stays taut when T = 0 at the top: mg = mv²/r, so v = √(gr) = √(9.8 × 1.2) = 3.43 m/s.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('49158667-7681-52dc-b1a3-1cc8e8b9c815', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 49, 49, 'A 0.50 kg ball is swung in a vertical circle of radius 1.2 m. Assume its speed is 6.0 m/s at both the top and the bottom. Calculate the tension in the string at the top of the circle. Take g = 9.8 N/kg.', 'diagram:circ-ch-vertical', 3, 'numeric'::answer_type, '10.1', 'N', NULL, false, 'The centripetal force needed is mv²/r = 0.50 × 36 ÷ 1.2 = 15.0 N, and the weight is mg = 0.50 × 9.8 = 4.90 N. (a) At the top the tension and the weight both point towards the centre: T + mg = 15.0, so T = 15.0 − 4.90 = 10.1 N. (b) At the bottom the tension points to the centre but the weight points away: T − mg = 15.0, so T = 19.9 N. (c) The string just stays taut when T = 0 at the top: mg = mv²/r, so v = √(gr) = √(9.8 × 1.2) = 3.43 m/s.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('ee75d0f9-dc58-5d8b-9cd7-98c54ebff759', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'igcse', NULL, NULL, 40, 40, 'A 0.20 kg bob hangs on a 1.0 m string. It moves in a horizontal circle with the string making 30° with the vertical. Calculate the time for one revolution. Take g = 9.8 N/kg.', 'diagram:circ-ch-conical', 4, 'numeric'::answer_type, '1.868', 's', NULL, false, 'Vertical: T cos30° = mg (no vertical acceleration). Horizontal: T sin30° = mv²/r. (a) Tension: T = mg/cos30° = 0.20 × 9.8 ÷ 0.866 = 2.26 N. (b) The radius is r = L sin30° = 1.0 × 0.50 = 0.500 m — not the string length. (c) Centripetal force = T sin30° = 1.13 N, so v² = Fr/m = 1.13 × 0.500 ÷ 0.20 and v = 1.68 m/s. (d) Period = 2πr/v = 2π × 0.500 ÷ 1.68 = 1.87 s.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('5bc4e23e-f46c-5eaf-ad19-477e3e23659b', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 50, 50, 'A 0.20 kg bob hangs on a 1.0 m string. It moves in a horizontal circle with the string making 30° with the vertical. Calculate the time for one revolution. Take g = 9.8 N/kg.', 'diagram:circ-ch-conical', 4, 'numeric'::answer_type, '1.868', 's', NULL, false, 'Vertical: T cos30° = mg (no vertical acceleration). Horizontal: T sin30° = mv²/r. (a) Tension: T = mg/cos30° = 0.20 × 9.8 ÷ 0.866 = 2.26 N. (b) The radius is r = L sin30° = 1.0 × 0.50 = 0.500 m — not the string length. (c) Centripetal force = T sin30° = 1.13 N, so v² = Fr/m = 1.13 × 0.500 ÷ 0.20 and v = 1.68 m/s. (d) Period = 2πr/v = 2π × 0.500 ÷ 1.68 = 1.87 s.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('7372e1fa-97d1-5b31-a3e3-4c3630e36ded', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'igcse', NULL, NULL, 41, 41, 'A 0.30 kg mass is whirled on the end of a 0.60 m string in a horizontal circle on a frictionless table. The string breaks if the tension exceeds 40 N. Calculate the maximum speed the mass can have without the string breaking.', NULL, 3, 'numeric'::answer_type, '8.944', 'm/s', NULL, false, 'The tension provides the centripetal force, T = mv²/r, so v = √(Tr/m) = √(40 × 0.60 ÷ 0.30) = √80 = 8.94 m/s. Any faster and the tension needed is more than 40 N.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('a11d040e-286d-526c-8f4f-385acdf4caae', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 51, 51, 'A 0.30 kg mass is whirled on the end of a 0.60 m string in a horizontal circle on a frictionless table. The string breaks if the tension exceeds 40 N. Calculate the maximum speed the mass can have without the string breaking.', NULL, 3, 'numeric'::answer_type, '8.944', 'm/s', NULL, false, 'The tension provides the centripetal force, T = mv²/r, so v = √(Tr/m) = √(40 × 0.60 ÷ 0.30) = √80 = 8.94 m/s. Any faster and the tension needed is more than 40 N.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('35a02402-31ce-5bf4-b4b1-c9e1bbc86ba0', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'igcse', NULL, NULL, 42, 42, 'The maximum friction force between a car’s tyres and a dry flat road is 0.85 times the car’s weight. Calculate the maximum speed at which the car can take a flat bend of radius 40 m. Take g = 9.8 N/kg.', 'diagram:circ-ch-flat-bend-mu', 3, 'numeric'::answer_type, '18.25', 'm/s', NULL, false, 'Maximum friction = 0.85 mg provides the centripetal force: 0.85 mg = mv²/r. The mass cancels, so v = √(0.85 × g × r) = √(0.85 × 9.8 × 40) = √333 = 18.3 m/s, about 65.7 km/h — the same for a small car and a heavy lorry.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('cb43fdc5-5fd6-548c-94cc-8fa80e96ed55', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 52, 52, 'The maximum friction force between a car’s tyres and a dry flat road is 0.85 times the car’s weight. Calculate the maximum speed at which the car can take a flat bend of radius 40 m. Take g = 9.8 N/kg.', 'diagram:circ-ch-flat-bend-mu', 3, 'numeric'::answer_type, '18.25', 'm/s', NULL, false, 'Maximum friction = 0.85 mg provides the centripetal force: 0.85 mg = mv²/r. The mass cancels, so v = √(0.85 × g × r) = √(0.85 × 9.8 × 40) = √333 = 18.3 m/s, about 65.7 km/h — the same for a small car and a heavy lorry.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('339731f1-f785-5f4b-a0fa-fd0cbe8ec0ff', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'igcse', NULL, NULL, 43, 43, 'A conical pendulum has a bob on a 0.75 m string. The string makes an angle of 40° with the vertical as the bob moves in a horizontal circle. Calculate the speed of the bob. Take g = 9.8 N/kg.', NULL, 4, 'numeric'::answer_type, '1.991', 'm/s', NULL, false, 'The radius is r = L sin40° = 0.75 × 0.643 = 0.482 m. Vertically T cosθ = mg and horizontally T sinθ = mv²/r. Dividing: tanθ = v²/(rg), so v = √(r g tanθ) = √(0.482 × 9.8 × 0.839) = 1.99 m/s. The mass cancels, so the bob’s mass is not needed.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('e5c11088-7d7c-510a-b9c7-f4de5b2b5bd2', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 53, 53, 'A conical pendulum has a bob on a 0.75 m string. The string makes an angle of 40° with the vertical as the bob moves in a horizontal circle. Calculate the speed of the bob. Take g = 9.8 N/kg.', NULL, 4, 'numeric'::answer_type, '1.991', 'm/s', NULL, false, 'The radius is r = L sin40° = 0.75 × 0.643 = 0.482 m. Vertically T cosθ = mg and horizontally T sinθ = mv²/r. Dividing: tanθ = v²/(rg), so v = √(r g tanθ) = √(0.482 × 9.8 × 0.839) = 1.99 m/s. The mass cancels, so the bob’s mass is not needed.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('0ac60da5-e106-55df-9cf0-3b1d2864ded2', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'igcse', NULL, NULL, 44, 44, 'A ball is swung on a string in a vertical circle of radius 0.90 m. Calculate the minimum speed it must have at the bottom of the circle for the string to stay taut all the way round. (Its speed changes as it rises: use conservation of energy.) Take g = 9.8 N/kg.', 'diagram:circ-ch-vertical-energy', 4, 'numeric'::answer_type, '6.641', 'm/s', NULL, false, 'At the top the string only just stays taut when T = 0, so mg = mv_top²/r and v_top² = gr = 9.8 × 0.90 = 8.82 m²/s². Rising a height 2r, the ball’s kinetic energy falls by mg(2r): ½mv_bottom² = ½mv_top² + mg(2r), so v_bottom² = v_top² + 4gr = 5gr. Then v_bottom = √(5 × 9.8 × 0.90) = √44.1 = 6.64 m/s.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('a453ae81-d4db-54fd-b114-e63240c39675', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 54, 54, 'A ball is swung on a string in a vertical circle of radius 0.90 m. Calculate the minimum speed it must have at the bottom of the circle for the string to stay taut all the way round. (Its speed changes as it rises: use conservation of energy.) Take g = 9.8 N/kg.', 'diagram:circ-ch-vertical-energy', 4, 'numeric'::answer_type, '6.641', 'm/s', NULL, false, 'At the top the string only just stays taut when T = 0, so mg = mv_top²/r and v_top² = gr = 9.8 × 0.90 = 8.82 m²/s². Rising a height 2r, the ball’s kinetic energy falls by mg(2r): ½mv_bottom² = ½mv_top² + mg(2r), so v_bottom² = v_top² + 4gr = 5gr. Then v_bottom = √(5 × 9.8 × 0.90) = √44.1 = 6.64 m/s.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('20d54b0b-5133-5d99-8c6f-fe0b71b6384c', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'igcse', NULL, NULL, 45, 45, 'A 0.25 kg ball is swung on a string in a vertical circle of radius 0.90 m. Its speed at the bottom of the circle is 7.0 m/s. Calculate the tension in the string at the top of the circle. Take g = 9.8 N/kg.', 'diagram:circ-ch-vertical-energy', 5, 'numeric'::answer_type, '1.361', 'N', 0.05, false, 'Energy is conserved between bottom and top, which are 2r = 1.8 m apart: v_top² = v_bottom² − 4gr = 49 − 4 × 9.8 × 0.90 = 13.7 m²/s². At the top, tension and weight both point to the centre: T + mg = mv_top²/r, so T = 0.25 × 13.7 ÷ 0.90 − 0.25 × 9.8 = 3.81 − 2.45 = 1.36 N. (Check the ball gets there: v_top² must be at least gr = 8.82, and it is.)', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('42d549d6-3b29-5eb6-9e99-8320c2c2f806', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 55, 55, 'A 0.25 kg ball is swung on a string in a vertical circle of radius 0.90 m. Its speed at the bottom of the circle is 7.0 m/s. Calculate the tension in the string at the top of the circle. Take g = 9.8 N/kg.', 'diagram:circ-ch-vertical-energy', 5, 'numeric'::answer_type, '1.361', 'N', 0.05, false, 'Energy is conserved between bottom and top, which are 2r = 1.8 m apart: v_top² = v_bottom² − 4gr = 49 − 4 × 9.8 × 0.90 = 13.7 m²/s². At the top, tension and weight both point to the centre: T + mg = mv_top²/r, so T = 0.25 × 13.7 ÷ 0.90 − 0.25 × 9.8 = 3.81 − 2.45 = 1.36 N. (Check the ball gets there: v_top² must be at least gr = 8.82, and it is.)', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('307f9352-6102-5e17-ac27-010e387d4d25', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 'igcse', NULL, NULL, 8, 8, 'Planet X has mass 4.0 × 10²⁴ kg and radius 5.0 × 10⁶ m. Calculate the weight of a 70 kg astronaut at a height of 5.0 × 10⁶ m above the surface of Planet X. Use G = 6.67 × 10⁻¹¹ N m² kg⁻².', 'diagram:grav-ch-planet', 2, 'numeric'::answer_type, '186.8', 'N', NULL, false, 'GM = 6.67 × 10⁻¹¹ × 4.0 × 10²⁴ = 2.67 × 10¹⁴. (a) At the surface g = GM/r² = 2.67 × 10¹⁴ ÷ (5.0 × 10⁶)² = 10.7 N/kg. (b) At 5.0 × 10⁶ m above the surface the distance from the centre is r = 1.0 × 10⁷ m, so g = 2.67 × 10¹⁴ ÷ (1.0 × 10⁷)² = 2.67 N/kg — doubling r divides g by 4. (c) W = mg: at the surface 70 × 10.7 = 747 N; at this height 70 × 2.67 = 187 N.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('d7802d7c-805c-508c-87f6-a6b89992cdc7', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 'a-level', '13.2', '9702 13.2 Gravitational force between point masses', 23, 23, 'Planet X has mass 4.0 × 10²⁴ kg and radius 5.0 × 10⁶ m. Calculate the weight of a 70 kg astronaut at a height of 5.0 × 10⁶ m above the surface of Planet X. Use G = 6.67 × 10⁻¹¹ N m² kg⁻².', 'diagram:grav-ch-planet', 2, 'numeric'::answer_type, '186.8', 'N', NULL, false, 'GM = 6.67 × 10⁻¹¹ × 4.0 × 10²⁴ = 2.67 × 10¹⁴. (a) At the surface g = GM/r² = 2.67 × 10¹⁴ ÷ (5.0 × 10⁶)² = 10.7 N/kg. (b) At 5.0 × 10⁶ m above the surface the distance from the centre is r = 1.0 × 10⁷ m, so g = 2.67 × 10¹⁴ ÷ (1.0 × 10⁷)² = 2.67 N/kg — doubling r divides g by 4. (c) W = mg: at the surface 70 × 10.7 = 747 N; at this height 70 × 2.67 = 187 N.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('e6b850e9-3aef-5e95-b119-7bcdc192a98c', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 'igcse', NULL, NULL, 9, 9, 'A satellite orbits Earth in a circle at an altitude of 600 km. Calculate its orbital period, in minutes. Use G = 6.67 × 10⁻¹¹ N m² kg⁻²; Earth’s mass = 5.97 × 10²⁴ kg and Earth’s radius = 6.37 × 10⁶ m.', 'diagram:grav-ch-leo', 3, 'numeric'::answer_type, '96.57', 'min', NULL, false, 'GM = 3.98 × 10¹⁴. The orbital radius is measured from the centre: r = 6.37 × 10⁶ + 6.0 × 10⁵ = 6.97 × 10⁶ m. Gravity provides the centripetal force: GMm/r² = mv²/r, so (a) v = √(GM/r) = √(3.98 × 10¹⁴ ÷ 6.97 × 10⁶) = 7560 m/s. (b) T = 2πr/v = 2π × 6.97 × 10⁶ ÷ 7558 = 5794 s = 96.6 minutes.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('a5fe5ac3-867f-5f69-9ff8-3ac1c8555ee2', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 'a-level', '13.2', '9702 13.2 Gravitational force between point masses', 24, 24, 'A satellite orbits Earth in a circle at an altitude of 600 km. Calculate its orbital period, in minutes. Use G = 6.67 × 10⁻¹¹ N m² kg⁻²; Earth’s mass = 5.97 × 10²⁴ kg and Earth’s radius = 6.37 × 10⁶ m.', 'diagram:grav-ch-leo', 3, 'numeric'::answer_type, '96.57', 'min', NULL, false, 'GM = 3.98 × 10¹⁴. The orbital radius is measured from the centre: r = 6.37 × 10⁶ + 6.0 × 10⁵ = 6.97 × 10⁶ m. Gravity provides the centripetal force: GMm/r² = mv²/r, so (a) v = √(GM/r) = √(3.98 × 10¹⁴ ÷ 6.97 × 10⁶) = 7560 m/s. (b) T = 2πr/v = 2π × 6.97 × 10⁶ ÷ 7558 = 5794 s = 96.6 minutes.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('3505b2da-6323-546a-8a18-d72b8b098c56', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 'igcse', NULL, NULL, 10, 10, 'A geostationary satellite has a period of 24 h. Calculate its altitude above Earth’s surface, in metres. Use G = 6.67 × 10⁻¹¹ N m² kg⁻²; Earth’s mass = 5.97 × 10²⁴ kg and Earth’s radius = 6.37 × 10⁶ m.', 'diagram:grav-ch-geo', 3, 'numeric'::answer_type, '3.586e7', 'm', NULL, false, 'T = 24 h = 86 400 s. Equate the gravitational force to the centripetal force: GM/r² = ω²r = 4π²r/T², so r³ = GMT²/4π². (a) r³ = 3.98 × 10¹⁴ × 86 400² ÷ (4π²) = 7.53 × 10²² m³, so r = 4.22 × 10⁷ m. (b) Altitude = r − R = 4.22 × 10⁷ − 6.37 × 10⁶ = 3.59 × 10⁷ m (about 36 000 km). (c) v = 2πr/T = 2π × 4.22 × 10⁷ ÷ 86 400 = 3070 m/s.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('c739e0f0-122f-509e-8bd0-d8ab2adbb68d', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 'a-level', '13.2', '9702 13.2 Gravitational force between point masses', 25, 25, 'A geostationary satellite has a period of 24 h. Calculate its altitude above Earth’s surface, in metres. Use G = 6.67 × 10⁻¹¹ N m² kg⁻²; Earth’s mass = 5.97 × 10²⁴ kg and Earth’s radius = 6.37 × 10⁶ m.', 'diagram:grav-ch-geo', 3, 'numeric'::answer_type, '3.586e7', 'm', NULL, false, 'T = 24 h = 86 400 s. Equate the gravitational force to the centripetal force: GM/r² = ω²r = 4π²r/T², so r³ = GMT²/4π². (a) r³ = 3.98 × 10¹⁴ × 86 400² ÷ (4π²) = 7.53 × 10²² m³, so r = 4.22 × 10⁷ m. (b) Altitude = r − R = 4.22 × 10⁷ − 6.37 × 10⁶ = 3.59 × 10⁷ m (about 36 000 km). (c) v = 2πr/T = 2π × 4.22 × 10⁷ ÷ 86 400 = 3070 m/s.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('3303e064-0b42-57f6-966c-d34acfdd896a', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 'igcse', NULL, NULL, 11, 11, 'Satellites A and B orbit the same planet. B’s orbital radius is 4 times A’s. If A’s orbital period is 2.0 h, calculate B’s orbital period, in hours.', 'diagram:grav-ch-two-orbits', 3, 'numeric'::answer_type, '16', 'h', NULL, false, 'For circular orbits T² ∝ r³, so T ∝ r^(3/2). (a) v = √(GM/r), so v ∝ 1/√r and v_B/v_A = 1/√4 = 1/2. (b) T_B/T_A = 4^(3/2) = 8. (c) T_B = 8 × 2.0 = 16 h. (d) F = GMm/r², so for equal masses F_B/F_A = 1/4² = 1/16 = 0.0625.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('028bdba4-fdbf-55de-959c-53e437544beb', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 'a-level', '13.2', '9702 13.2 Gravitational force between point masses', 26, 26, 'Satellites A and B orbit the same planet. B’s orbital radius is 4 times A’s. If A’s orbital period is 2.0 h, calculate B’s orbital period, in hours.', 'diagram:grav-ch-two-orbits', 3, 'numeric'::answer_type, '16', 'h', NULL, false, 'For circular orbits T² ∝ r³, so T ∝ r^(3/2). (a) v = √(GM/r), so v ∝ 1/√r and v_B/v_A = 1/√4 = 1/2. (b) T_B/T_A = 4^(3/2) = 8. (c) T_B = 8 × 2.0 = 16 h. (d) F = GMm/r², so for equal masses F_B/F_A = 1/4² = 1/16 = 0.0625.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('f0840607-d245-5277-8a6a-069edc96bcdb', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 'igcse', NULL, NULL, 12, 12, 'The Earth–Moon distance is 3.84 × 10⁸ m, and Earth’s mass is 81 times the Moon’s. At what distance from Earth does a spacecraft on the line between them feel zero net gravitational force? Give your answer in metres.', 'diagram:grav-ch-balance', 4, 'numeric'::answer_type, '3.456e8', 'm', NULL, false, 'Let the craft be x from Earth, so (d − x) from the Moon. Set GM_E m/x² = GM_M m/(d − x)². With M_E = 81 M_M: 81/x² = 1/(d − x)². Take the square root: 9/x = 1/(d − x), so 9(d − x) = x and x = 0.9d = 0.9 × 3.84 × 10⁸ = 3.46 × 10⁸ m from Earth (3.84 × 10⁷ m from the Moon).', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('90496db8-be36-55b5-8462-f611ad3b8a18', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 'a-level', '13.2', '9702 13.2 Gravitational force between point masses', 27, 27, 'The Earth–Moon distance is 3.84 × 10⁸ m, and Earth’s mass is 81 times the Moon’s. At what distance from Earth does a spacecraft on the line between them feel zero net gravitational force? Give your answer in metres.', 'diagram:grav-ch-balance', 4, 'numeric'::answer_type, '3.456e8', 'm', NULL, false, 'Let the craft be x from Earth, so (d − x) from the Moon. Set GM_E m/x² = GM_M m/(d − x)². With M_E = 81 M_M: 81/x² = 1/(d − x)². Take the square root: 9/x = 1/(d − x), so 9(d − x) = x and x = 0.9d = 0.9 × 3.84 × 10⁸ = 3.46 × 10⁸ m from Earth (3.84 × 10⁷ m from the Moon).', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('53b22e25-d187-511d-9709-edbd13551b4f', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 'igcse', NULL, NULL, 13, 13, 'At what height above Earth’s surface is the gravitational field strength 4.9 N/kg? Give your answer in metres. Use G = 6.67 × 10⁻¹¹ N m² kg⁻²; Earth’s mass = 5.97 × 10²⁴ kg and Earth’s radius = 6.37 × 10⁶ m.', NULL, 3, 'numeric'::answer_type, '2.645e6', 'm', NULL, false, 'g = GM/r², so r = √(GM/g) = √(3.98 × 10¹⁴ ÷ 4.9) = 9.01 × 10⁶ m from the centre of the Earth. The height is the distance from the surface: h = r − R = 9.01 × 10⁶ − 6.37 × 10⁶ = 2.64 × 10⁶ m. (Half the surface value of g is reached about 0.41 R above the surface, not at R/2.)', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('c5735dc3-7b95-5b0d-81f9-103c3117651e', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 'a-level', '13.2', '9702 13.2 Gravitational force between point masses', 28, 28, 'At what height above Earth’s surface is the gravitational field strength 4.9 N/kg? Give your answer in metres. Use G = 6.67 × 10⁻¹¹ N m² kg⁻²; Earth’s mass = 5.97 × 10²⁴ kg and Earth’s radius = 6.37 × 10⁶ m.', NULL, 3, 'numeric'::answer_type, '2.645e6', 'm', NULL, false, 'g = GM/r², so r = √(GM/g) = √(3.98 × 10¹⁴ ÷ 4.9) = 9.01 × 10⁶ m from the centre of the Earth. The height is the distance from the surface: h = r − R = 9.01 × 10⁶ − 6.37 × 10⁶ = 2.64 × 10⁶ m. (Half the surface value of g is reached about 0.41 R above the surface, not at R/2.)', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('053cc3a9-2c40-5297-958e-fd00a4b2368b', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 'igcse', NULL, NULL, 14, 14, 'The Moon orbits Earth in an almost circular orbit of radius 3.84 × 10⁸ m. Calculate the Moon’s orbital period, in days. Use G = 6.67 × 10⁻¹¹ N m² kg⁻²; Earth’s mass = 5.97 × 10²⁴ kg.', 'diagram:grav-ch-moon-period', 3, 'numeric'::answer_type, '27.42', 'days', NULL, false, 'Gravity provides the centripetal force, so v = √(GM/r) = √(3.98 × 10¹⁴ ÷ 3.84 × 10⁸) = 1020 m/s. T = 2πr/v = 2π × 3.84 × 10⁸ ÷ 1020 = 2.37 × 10⁶ s = 27.4 days, which matches the real sidereal month (27.3 days).', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('33034fe3-8cc9-5fce-924b-0b5aad357d92', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 'a-level', '13.2', '9702 13.2 Gravitational force between point masses', 29, 29, 'The Moon orbits Earth in an almost circular orbit of radius 3.84 × 10⁸ m. Calculate the Moon’s orbital period, in days. Use G = 6.67 × 10⁻¹¹ N m² kg⁻²; Earth’s mass = 5.97 × 10²⁴ kg.', 'diagram:grav-ch-moon-period', 3, 'numeric'::answer_type, '27.42', 'days', NULL, false, 'Gravity provides the centripetal force, so v = √(GM/r) = √(3.98 × 10¹⁴ ÷ 3.84 × 10⁸) = 1020 m/s. T = 2πr/v = 2π × 3.84 × 10⁸ ÷ 1020 = 2.37 × 10⁶ s = 27.4 days, which matches the real sidereal month (27.3 days).', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('2fd54e46-bf15-5190-827d-3e012ea5253a', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 'igcse', NULL, NULL, 15, 15, 'A moon orbits a planet in a circle of radius 4.22 × 10⁸ m with a period of 1.77 days. Calculate the mass of the planet. Use G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 4, 'numeric'::answer_type, '1.902e27', 'kg', NULL, false, 'T = 1.77 × 86 400 = 1.529 × 10⁵ s. From GMm/r² = mω²r = 4π²mr/T², the moon’s mass cancels and M = 4π²r³/(GT²) = 4π² × (4.22 × 10⁸)³ ÷ (6.67 × 10⁻¹¹ × (1.529 × 10⁵)²) = 1.90 × 10²⁷ kg — about 300 Earth masses (this is Jupiter and its moon Io).', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('333a136d-e32d-5008-8c02-2a30bab299ca', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 'a-level', '13.2', '9702 13.2 Gravitational force between point masses', 30, 30, 'A moon orbits a planet in a circle of radius 4.22 × 10⁸ m with a period of 1.77 days. Calculate the mass of the planet. Use G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 4, 'numeric'::answer_type, '1.902e27', 'kg', NULL, false, 'T = 1.77 × 86 400 = 1.529 × 10⁵ s. From GMm/r² = mω²r = 4π²mr/T², the moon’s mass cancels and M = 4π²r³/(GT²) = 4π² × (4.22 × 10⁸)³ ÷ (6.67 × 10⁻¹¹ × (1.529 × 10⁵)²) = 1.90 × 10²⁷ kg — about 300 Earth masses (this is Jupiter and its moon Io).', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('28280053-9257-5aad-94d6-88f1c9e64a82', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 'igcse', NULL, NULL, 16, 16, 'A satellite orbits Earth once every 90 minutes in a circular orbit. Calculate its altitude above Earth’s surface, in metres. Use G = 6.67 × 10⁻¹¹ N m² kg⁻²; Earth’s mass = 5.97 × 10²⁴ kg and Earth’s radius = 6.37 × 10⁶ m.', 'diagram:grav-ch-leo-h', 4, 'numeric'::answer_type, '2.803e5', 'm', NULL, false, 'T = 90 × 60 = 5400 s. From GM/r² = 4π²r/T², r³ = GMT²/4π² = 3.98 × 10¹⁴ × 5400² ÷ 4π² = 2.94 × 10²⁰ m³, so r = 6.65 × 10⁶ m. The altitude is r − R = 6.65 × 10⁶ − 6.37 × 10⁶ = 2.80 × 10⁵ m, about 280 km. (Forgetting to subtract Earth’s radius would give the wrong answer by a factor of about 24.)', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('fbace73d-607a-5d6f-bef7-6c250ad8c713', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 'a-level', '13.2', '9702 13.2 Gravitational force between point masses', 31, 31, 'A satellite orbits Earth once every 90 minutes in a circular orbit. Calculate its altitude above Earth’s surface, in metres. Use G = 6.67 × 10⁻¹¹ N m² kg⁻²; Earth’s mass = 5.97 × 10²⁴ kg and Earth’s radius = 6.37 × 10⁶ m.', 'diagram:grav-ch-leo-h', 4, 'numeric'::answer_type, '2.803e5', 'm', NULL, false, 'T = 90 × 60 = 5400 s. From GM/r² = 4π²r/T², r³ = GMT²/4π² = 3.98 × 10¹⁴ × 5400² ÷ 4π² = 2.94 × 10²⁰ m³, so r = 6.65 × 10⁶ m. The altitude is r − R = 6.65 × 10⁶ − 6.37 × 10⁶ = 2.80 × 10⁵ m, about 280 km. (Forgetting to subtract Earth’s radius would give the wrong answer by a factor of about 24.)', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('89bddc8f-c3c2-5894-8c03-1c3f2260c9b0', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 'igcse', NULL, NULL, 17, 17, 'A satellite orbits just above the surface of a planet of uniform density 5500 kg/m³, so its orbital radius is the planet’s radius R. Show that the period does not depend on the size of the planet, and calculate it, in seconds. Use G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 5, 'numeric'::answer_type, '5069', 's', NULL, false, 'Mass of the planet: M = ρ × (4/3)πR³. Gravity provides the centripetal force: GM/R² = 4π²R/T², so T² = 4π²R³/(GM) = 4π²R³ ÷ (G × (4/3)πR³ρ) = 3π/(Gρ). R cancels, so only the density matters: T = √(3π/(Gρ)) = √(3π ÷ (6.67 × 10⁻¹¹ × 5500)) = √(2.57 × 10⁷) = 5070 s (about 84 min). Every rocky planet of this density has a surface-skimming orbit of about 84 minutes.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('dc80671e-0b78-5c20-a654-adeffeff9917', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 'a-level', '13.2', '9702 13.2 Gravitational force between point masses', 32, 32, 'A satellite orbits just above the surface of a planet of uniform density 5500 kg/m³, so its orbital radius is the planet’s radius R. Show that the period does not depend on the size of the planet, and calculate it, in seconds. Use G = 6.67 × 10⁻¹¹ N m² kg⁻².', NULL, 5, 'numeric'::answer_type, '5069', 's', NULL, false, 'Mass of the planet: M = ρ × (4/3)πR³. Gravity provides the centripetal force: GM/R² = 4π²R/T², so T² = 4π²R³/(GM) = 4π²R³ ÷ (G × (4/3)πR³ρ) = 3π/(Gρ). R cancels, so only the density matters: T = √(3π/(Gρ)) = √(3π ÷ (6.67 × 10⁻¹¹ × 5500)) = √(2.57 × 10⁷) = 5070 s (about 84 min). Every rocky planet of this density has a surface-skimming orbit of about 84 minutes.', 3) ON CONFLICT (id) DO NOTHING;
